import { describe, expect, it } from "vitest";
import {
  ConversationEventType,
  type ConversationEvent,
  type MemoryEntryState,
  type SkillCatalog,
} from "../types";
import { deriveSkillMemoryView, DISCOVERED_FACTS_SLOT } from "./deriveSkillMemoryView";

function entry(overrides: Partial<MemoryEntryState>): MemoryEntryState {
  return { value: null, source: null, scope: "skill", description: null, ...overrides };
}

function memoryWrite(name: string, value: unknown): ConversationEvent {
  return {
    __typename: "ConversationEvent",
    id: `write-${name}`,
    conversationEventType: ConversationEventType.MemorySet,
    name,
    slotValue: value,
    timestamp: "2026-01-01T00:00:00.000Z",
    originalTimestamp: 0,
    metadata: { parseData: {} },
  };
}

function derive(
  memory: Record<string, MemoryEntryState>,
  catalog: SkillCatalog | null = null,
  events: ConversationEvent[] = [],
) {
  return deriveSkillMemoryView(memory, catalog, events);
}

describe("deriveSkillMemoryView", () => {
  it("groups entries into per-skill, project and system sections", () => {
    const view = derive({
      "travel_notice.destination": entry({ value: "Atlantis", source: "llm" }),
      "project.selected_card_id": entry({ value: "c1", scope: "project", source: "tool" }),
      "system.correction_resume_point": entry({ value: "step-2", scope: "system" }),
    });
    expect(view.sections.map((section) => section.title)).toEqual([
      "Travel notice",
      "Project",
      "System",
    ]);
    expect(view.sections.map((section) => section.kind)).toEqual(["skill", "project", "system"]);
    expect(view.sections[0].rows[0]).toMatchObject({
      name: "destination",
      fullName: "travel_notice.destination",
      source: "llm",
    });
    expect(view.sections[1].rows[0].name).toBe("selected_card_id");
  });

  it("creates one section per skill in the payload, not just the active one", () => {
    const view = derive(
      {
        "travel_notice.destination": entry({ value: "Lisbon" }),
        "travel_notice.start_date": entry({ value: null }),
        "card_operations.blocked_card": entry({ value: "1234" }),
      },
      null,
      // start_date has a witnessed write, so its dash row survives the filter.
      [memoryWrite("travel_notice.start_date", null)],
    );
    const skillSections = view.sections.filter((section) => section.kind === "skill");
    expect(skillSections.map((section) => section.title)).toEqual([
      "Travel notice",
      "Card operations",
    ]);
    expect(skillSections[0].rows.map((row) => row.name)).toEqual(["start_date", "destination"]);
    expect(skillSections[1].rows.map((row) => row.name)).toEqual(["blocked_card"]);
  });

  it("titles skill sections from the catalog name, humanized id otherwise", () => {
    const catalog = {
      travel_notice: { name: "Travel Notice ✈️" },
    } as unknown as SkillCatalog;
    const view = derive(
      {
        "travel_notice.destination": entry({ value: "Lisbon" }),
        "book_flight.passengers": entry({ value: 2 }),
      },
      catalog,
    );
    expect(view.sections.map((section) => section.title)).toEqual([
      "Travel Notice ✈️",
      "Book flight",
    ]);
  });

  it("strips only the skill prefix from nested entry names", () => {
    const view = derive({
      "project.address.city": entry({ value: "Atlantis", scope: "project" }),
    });
    expect(view.sections[0].rows[0]).toMatchObject({
      name: "address.city",
      fullName: "project.address.city",
    });
  });

  it("splits discovered facts into a Discovered section, newest first", () => {
    const view = derive({
      [DISCOVERED_FACTS_SLOT]: entry({
        scope: "system",
        value: [
          {
            key: "travels_with_partner",
            value: true,
            description: "Mentioned travelling with a partner.",
            turn_idx: 3,
            confidence: 0.9,
            captured_by_skill: "travel_notice",
          },
          { key: "has_pet", value: "dog", description: "" },
          "not-a-fact",
        ],
      }),
    });
    expect(view.sections).toEqual([
      {
        title: "Discovered",
        kind: "discovered",
        rows: [
          {
            name: "has_pet",
            fullName: "has_pet",
            value: "dog",
            source: "llm",
            description: null,
          },
          {
            name: "travels_with_partner",
            fullName: "travels_with_partner",
            value: true,
            source: "llm",
            description: "Mentioned travelling with a partner. (captured by travel_notice)",
          },
        ],
      },
    ]);
  });

  it("tolerates a non-list scratchpad value", () => {
    const view = derive({
      [DISCOVERED_FACTS_SLOT]: entry({ scope: "system", value: "corrupt" }),
    });
    expect(view.sections).toEqual([]);
  });

  it("sorts rows and sections newest-written first, cleared entries at the bottom", () => {
    const view = derive(
      {
        "travel_notice.destination": entry({ value: "Lisbon" }),
        "travel_notice.start_date": entry({ value: "2026-09-01" }),
        // Written then cleared: keeps its dash row below the filled ones.
        "travel_notice.end_date": entry({ value: null }),
        "project.selected_card_id": entry({ value: "c1", scope: "project" }),
      },
      null,
      [
        memoryWrite("travel_notice.end_date", "2026-09-10"),
        memoryWrite("travel_notice.destination", "Lisbon"),
        memoryWrite("project.selected_card_id", "c1"),
        memoryWrite("travel_notice.start_date", "2026-09-01"),
        memoryWrite("travel_notice.end_date", null),
      ],
    );
    expect(view.sections.map((section) => section.title)).toEqual(["Travel notice", "Project"]);
    expect(view.sections[0].rows.map((row) => row.name)).toEqual([
      "end_date",
      "start_date",
      "destination",
    ]);
  });

  it("hides entries that were never set, keeps cleared-but-once-written ones", () => {
    const view = derive(
      {
        "travel_notice.destination": entry({ value: "Lisbon" }),
        // Never set: no value, no write — hidden.
        "travel_notice.origin": entry({ value: null }),
        // Written then cleared: value null but a write exists — visible with a dash.
        "travel_notice.end_date": entry({ value: null }),
      },
      null,
      [memoryWrite("travel_notice.end_date", null)],
    );
    expect(view.sections[0].rows.map((row) => row.name)).toEqual(["end_date", "destination"]);
  });

  it("omits a section whose entries were all never set", () => {
    const view = derive({
      "travel_notice.destination": entry({ value: null }),
      "travel_notice.origin": entry({ value: null }),
      "project.selected_card_id": entry({ value: "c1", scope: "project" }),
    });
    expect(view.sections.map((section) => section.title)).toEqual(["Project"]);
  });

  it("returns no sections when every entry was never set", () => {
    const view = derive({
      "travel_notice.destination": entry({ value: null }),
      "project.selected_card_id": entry({ value: null, scope: "project" }),
      "system.correction_resume_point": entry({ value: null, scope: "system" }),
    });
    expect(view.sections).toEqual([]);
  });

  it("keeps a filled entry with no witnessed write", () => {
    const view = derive({
      // Filled before the inspector joined: value present, no write event.
      "travel_notice.destination": entry({ value: "Lisbon" }),
    });
    expect(view.sections[0].rows.map((row) => row.name)).toEqual(["destination"]);
  });
});
